const body = $input.first().json.body;

const required = ['amount', 'category', 'description'];
const missing = required.filter(f => !body[f]);
if (missing.length) {
  return [{ json: { valid: false, error: `Missing: ${missing.join(', ')}` } }];
}

const amount = parseFloat(body.amount);
if (isNaN(amount) || amount <= 0) {
  return [{ json: { valid: false, error: 'amount must be a positive number' } }];
}

const validCategories = [
  'food_dining', 'groceries', 'transport', 'entertainment',
  'shopping', 'health', 'subscriptions', 'utilities',
  'travel', 'education', 'personal_care', 'gifts', 'other'
];
const category = validCategories.includes(body.category) ? body.category : 'other';

return [{
  json: {
    valid: true,
    mode: 'log',
    amount,
    currency: body.currency || 'USD',
    category,
    description: body.description.trim().slice(0, 200),
    merchant: body.merchant || '',
    isEssential: body.is_essential === true || body.is_essential === 'true',
    note: body.note || '',
    expenseDate: body.expense_date || new Date().toISOString().split('T')[0],
    loggedAt: new Date().toISOString()
  }
}];

// Works for both the log mode (after saving) and the weekly report mode
const allRows = $('Load All Expenses').all().map(r => r.json);
const mode = $input.context?.['Validate Expense'] ? 'log' : 'weekly';

const now = new Date();
const startOfWeek = new Date(now);
startOfWeek.setDate(now.getDate() - now.getDay()); // Sunday
startOfWeek.setHours(0,0,0,0);

const startOfMonth = new Date(now.getFullYear(), now.getMonth(), 1);
const startOfLastMonth = new Date(now.getFullYear(), now.getMonth() - 1, 1);
const endOfLastMonth = new Date(now.getFullYear(), now.getMonth(), 0);

function parseRows(rows, from, to) {
  return rows.filter(r => {
    const d = new Date(r.expense_date || r.logged_at);
    return d >= from && (!to || d <= to);
  }).map(r => ({
    date: r.expense_date,
    amount: parseFloat(r.amount) || 0,
    category: r.category || 'other',
    description: r.description || '',
    merchant: r.merchant || '',
    isEssential: r.is_essential === 'TRUE' || r.is_essential === true
  }));
}

const thisWeek = parseRows(allRows, startOfWeek);
const thisMonth = parseRows(allRows, startOfMonth);
const lastMonth = parseRows(allRows, startOfLastMonth, endOfLastMonth);

function sumByCategory(expenses) {
  const map = {};
  for (const e of expenses) {
    map[e.category] = (map[e.category] || 0) + e.amount;
  }
  return Object.entries(map)
    .sort((a, b) => b[1] - a[1])
    .map(([cat, total]) => ({ category: cat, total: parseFloat(total.toFixed(2)) }));
}

const weekTotal = thisWeek.reduce((s, e) => s + e.amount, 0);
const monthTotal = thisMonth.reduce((s, e) => s + e.amount, 0);
const lastMonthTotal = lastMonth.reduce((s, e) => s + e.amount, 0);
const essentialPct = thisMonth.length
  ? Math.round((thisMonth.filter(e => e.isEssential).reduce((s,e) => s+e.amount,0) / monthTotal) * 100)
  : 0;

// Top merchants this month
const merchantMap = {};
for (const e of thisMonth) {
  if (e.merchant) merchantMap[e.merchant] = (merchantMap[e.merchant] || 0) + e.amount;
}
const topMerchants = Object.entries(merchantMap)
  .sort((a,b) => b[1]-a[1]).slice(0, 5)
  .map(([m, t]) => ({ merchant: m, total: parseFloat(t.toFixed(2)) }));

// Largest single expenses this week
const biggestThisWeek = [...thisWeek].sort((a,b) => b.amount - a.amount).slice(0, 3);

return [{
  json: {
    mode: 'report',
    weekTotal: parseFloat(weekTotal.toFixed(2)),
    monthTotal: parseFloat(monthTotal.toFixed(2)),
    lastMonthTotal: parseFloat(lastMonthTotal.toFixed(2)),
    monthVsLastMonth: lastMonthTotal > 0
      ? parseFloat(((monthTotal - lastMonthTotal) / lastMonthTotal * 100).toFixed(1))
      : null,
    essentialPct,
    weekByCategory: sumByCategory(thisWeek),
    monthByCategory: sumByCategory(thisMonth),
    topMerchants,
    biggestThisWeek,
    transactionCountWeek: thisWeek.length,
    transactionCountMonth: thisMonth.length,
    currency: allRows[0]?.currency || 'USD',
    reportDate: now.toISOString().split('T')[0]
  }
}];

const stats = $('Compute Spending Stats').first().json;
const budgetRows = $input.all().map(r => r.json);

// Budget sheet: columns category | monthly_budget
const budgets = {};
for (const row of budgetRows) {
  if (row.category && row.monthly_budget) {
    budgets[row.category] = parseFloat(row.monthly_budget) || 0;
  }
}

// Budget status per category
const budgetStatus = stats.monthByCategory.map(item => {
  const budget = budgets[item.category] || null;
  const pct = budget ? Math.round((item.total / budget) * 100) : null;
  const over = budget && item.total > budget;
  return { ...item, budget, pct, over };
});

const totalBudget = Object.values(budgets).reduce((s, v) => s + v, 0);
const overBudgetCategories = budgetStatus.filter(b => b.over);

return [{
  json: {
    ...stats,
    budgets,
    budgetStatus,
    totalBudget,
    overBudgetCategories
  }
}];

