const coaching = $input.first().json.text || $input.first().json.content?.[0]?.text || '';
const d = $('Merge Budget Data').first().json;

function esc(s) { return String(s||'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;'); }

const catBar = (spent, budget) => {
  if (!budget) return '';
  const pct = Math.min(100, Math.round((spent / budget) * 100));
  const color = pct >= 100 ? '#dc2626' : pct >= 80 ? '#d97706' : '#16a34a';
  return `<div style="background:#f0f0f0;border-radius:4px;height:6px;margin-top:4px"><div style="background:${color};width:${pct}%;height:6px;border-radius:4px"></div></div>`;
};

const categoryRows = d.budgetStatus.map(b => `
  <div style="padding:10px 0;border-bottom:1px solid #f0f0f0">
    <div style="display:flex;justify-content:space-between;font-size:14px">
      <span style="color:#333">${esc(b.category.replace(/_/g,' '))}</span>
      <span style="color:${b.over ? '#dc2626' : '#333'};font-weight:${b.over ? '600' : '400'}">
        ${esc(d.currency)}${b.total.toFixed(2)}${b.budget ? ` / ${esc(d.currency)}${b.budget}` : ''}
      </span>
    </div>
    ${catBar(b.total, b.budget)}
  </div>`).join('');

const coachingHtml = coaching
  .replace(/\*\*(.+?)\*\*/g, '<strong>$1</strong>')
  .replace(/\n\n/g, '</p><p style="margin:0 0 12px">')
  .replace(/\n/g, '<br>');

const trendArrow = d.monthVsLastMonth !== null
  ? (d.monthVsLastMonth > 0 ? `<span style="color:#dc2626">↑${d.monthVsLastMonth}%</span>` : `<span style="color:#16a34a">↓${Math.abs(d.monthVsLastMonth)}%</span>`)
  : '';

const html = `<!DOCTYPE html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"></head>
<body style="margin:0;padding:16px;background:#f7f7f5;font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',sans-serif;color:#1a1a1a">
<div style="max-width:580px;margin:0 auto">
  <div style="background:#1a1a2e;color:#fff;padding:20px 24px;border-radius:10px 10px 0 0">
    <div style="font-size:11px;letter-spacing:1px;text-transform:uppercase;color:#8888aa;margin-bottom:4px">Weekly Spending Report</div>
    <div style="font-size:22px;font-weight:700">${esc(d.currency)} ${d.weekTotal.toFixed(2)} <span style="font-size:14px;font-weight:400;color:#aaa">this week</span></div>
    <div style="margin-top:6px;font-size:13px;color:#aaa">${esc(d.currency)} ${d.monthTotal.toFixed(2)} month-to-date ${trendArrow}</div>
  </div>

  <div style="background:#fff;padding:20px 24px;border-left:1px solid #eee;border-right:1px solid #eee">
    <div style="font-size:13px;font-weight:700;text-transform:uppercase;letter-spacing:0.5px;color:#888;margin-bottom:4px">Coach's Note</div>
    <p style="margin:0 0 12px;font-size:15px;line-height:1.7;color:#333">${coachingHtml}</p>
  </div>

  <div style="background:#fff;padding:20px 24px;border-left:1px solid #eee;border-right:1px solid #eee;border-top:4px solid #f0f0f0">
    <div style="font-size:13px;font-weight:700;text-transform:uppercase;letter-spacing:0.5px;color:#888;margin-bottom:8px">Categories — month to date</div>
    ${categoryRows}
  </div>

  ${d.topMerchants.length ? `<div style="background:#fff;padding:20px 24px;border-left:1px solid #eee;border-right:1px solid #eee;border-top:4px solid #f0f0f0">
    <div style="font-size:13px;font-weight:700;text-transform:uppercase;letter-spacing:0.5px;color:#888;margin-bottom:8px">Top merchants this month</div>
    ${d.topMerchants.map(m => `<div style="display:flex;justify-content:space-between;font-size:14px;padding:6px 0;border-bottom:1px solid #f8f8f8"><span>${esc(m.merchant)}</span><span>${esc(d.currency)}${m.total.toFixed(2)}</span></div>`).join('')}
  </div>` : ''}

  <div style="background:#1a1a2e;color:#666;font-size:11px;padding:12px 24px;border-radius:0 0 10px 10px;font-family:monospace;text-align:center">
    Personal Spending Coach · ${d.reportDate} · ${d.transactionCountMonth} transactions logged this month
  </div>
</div>
</body></html>`;

return [{ json: { html, weekTotal: d.weekTotal, currency: d.currency, overCount: d.overBudgetCategories.length } }];
